23	
24	const isAlive = (cell: Cell, liveCells: Cell[]): boolean =>
25	  liveCells.some((liveCell) => isSameCell(cell, liveCell));
26	
27	const NEIGHBOR_OFFSETS: Cell[] = [
28	  [-1, -1],
29	  [-1, 0],
30	  [-1, 1],
31	  [0, -1],
32	  [0, 1],
33	  [1, -1],
34	  [1, 0],
35	  [1, 1],
36	];
37	
38	const neighborsOf = ([x, y]: Cell): Cell[] =>
39	  NEIGHBOR_OFFSETS.map(([dx, dy]) => [x + dx, y + dy]);
40	
41	const birthCandidates = (liveCells: Cell[]): Cell[] =>
42	  liveCells
43	    .flatMap(neighborsOf)
44	    .filter((cell) => !isAlive(cell, liveCells))
45	    .filter(
46	      (cell, index, cells) =>
47	        index === cells.findIndex((other) => isSameCell(cell, other)),
48	    );
