50	export function nextGeneration(liveCells: Cell[]): Cell[] {
51	  const survivors = liveCells.filter((cell) =>
52	    survives(countLiveNeighbors(cell, liveCells)),
53	  );
54	  const born = birthCandidates(liveCells).filter((cell) =>
55	    isBorn(countLiveNeighbors(cell, liveCells)),
56	  );
57	  return [...survivors, ...born];
58	}
